            // Identity
            B.q("sa-m3-5", "sa-identity", "A legacy app moved to Azure VMs needs LDAP and Kerberos authentication, and the team does not want to run domain controllers. What do you recommend?", listOf("Microsoft Entra Domain Services", "Microsoft Entra ID with app registrations only", "Install AD DS on two Azure VMs", "Microsoft Entra External ID"), setOf(0), "Microsoft Entra Domain Services is a managed domain: Microsoft runs the domain controllers, and VMs can join it and use LDAP, Kerberos and NTLM, with users synchronised from Entra ID.",
                scenario = "Pellham Transport lifted an old dispatch app to Azure VMs. The app checks passwords with LDAP and uses Kerberos, and the newer Android driver app reads from it. The IT team is small and wants no domain controllers to patch.",
                whyWrong = mapOf(
