            // Authorization and secrets
            B.q("sa-m3-9", "sa-authorization", "Team leads must be able to grant their developers access in their own subscription, but only the Reader and Contributor roles, never Owner or User Access Administrator. What do you recommend?", listOf("Make each team lead an Owner of the subscription", "Assign User Access Administrator to each team lead", "Ask the central team to make every assignment", "Assign the Role Based Access Control Administrator role with a condition that limits the roles it can assign"), setOf(3), "Role Based Access Control Administrator can manage role assignments, and a condition on the assignment can restrict which roles, and even which kinds of principal, it may assign. Team leads can then grant Reader and Contributor but nothing more powerful.",
                scenario = "At Thornbury Software, each Android product team has its own subscription. The central cloud team is a bottleneck for every access request but will not hand out full control.",
                whyWrong = mapOf(
