            // Data: relational
            B.q("sa-m3-17", "sa-relational", "The audit team must be able to prove that no one, administrators included, has secretly changed past rows in the payments table. What do you recommend?", listOf("Ledger tables in Azure SQL Database, with database digests stored in immutable storage", "Dynamic data masking", "Row-level security", "A read-only database lock"), setOf(0), "The ledger feature keeps a cryptographic record of every change to ledger tables. Digests saved to immutable storage let you verify later that no row was tampered with, even by an administrator.",
                scenario = "Fennick Payments' Android wallet records every transfer in Azure SQL Database. Its regulator wants evidence that the history cannot be quietly edited.",
