            B.q("sa-m3-20", "sa-relational", "A MySQL-based catalogue gets ten reads for every write, and reads are slowing down. How do you scale reads on Azure Database for MySQL flexible server with the least change?", listOf("Move to a bigger server", "Add read replicas and send read-only queries to them", "Shard the data across ten servers", "Switch to Azure SQL Database"), setOf(1), "Read replicas are copies kept in sync from the primary. Sending read-only queries to them spreads the read load, while writes stay on the primary.",
                scenario = "Nettlefield Garden Centres' Android plant-catalogue app reads product data from MySQL flexible server constantly, but updates are rare. Pages slow down every spring weekend.",
