            B.q("sa-m3-24", "sa-nonrelational", "A SAP HANA system needs enterprise NFS file storage with very low latency, high throughput and snapshots, as a managed service. What do you recommend?", listOf("Azure Files standard", "Azure NetApp Files", "Blob Storage with NFS 3.0", "Azure Data Lake Storage"), setOf(1), "Azure NetApp Files is a high-performance file service for demanding workloads such as SAP HANA and HPC. It offers NFS and SMB with sub-millisecond latency and fast space-efficient snapshots.",
                scenario = "Kestrel Brewing's SAP system, which feeds stock levels to its Android sales app, is moving to Azure. SAP's guidance calls for high-performance NFS storage for HANA.",
                whyWrong = mapOf(
