            B.q("sa-m3-25", "sa-nonrelational", "Images uploaded in Europe must be copied automatically to a storage account in Australia so Australian users load them from nearby. What do you recommend?", listOf("GRS on the European account", "Object replication from the European account to an account in Australia", "AzCopy run by hand each day", "A second container in the same account"), setOf(1), "Object replication copies block blobs asynchronously from a source account to a destination account you choose, in any region. It needs blob versioning on both accounts and the change feed on the source.",
                scenario = "Wanderlight's Android travel app lets users upload trip photos, stored in West Europe. Half its users are in Australia and complain that photos load slowly.",
