            // Business continuity: backup and disaster recovery
            B.q("sa-m3-31", "sa-backup-dr", "Managed disks must be backed up several times a day with no agent in the VM and no effect on the running app. What do you recommend?", listOf("Azure Disk Backup to a Backup vault", "The MARS agent", "Copy the VHD files by hand", "Turn on geo-redundant storage for the disks"), setOf(0), "Azure Disk Backup takes incremental snapshots of managed disks on a schedule, several times a day if needed, through a Backup vault. It needs no agent and does not interrupt the VM.",
                scenario = "Owlbridge's video transcoding VMs keep work in progress on data disks. The team behind the Android video app wants restore points every few hours without installing anything in the VMs.",
                whyWrong = mapOf(
                    1 to "MARS is an agent installed in Windows that backs up files, the opposite of the requirement.",
                    2 to "Manual copies are slow, inconsistent and not scheduled.",
                    3 to "Managed disks do not offer GRS, and replication is not backup anyway.",
                ),
            ),
            B.q("sa-m3-32", "sa-backup-dr", "On-premises Hyper-V VMs and a SQL Server must be backed up to Azure with application-consistent backups and fast local restores. What do you recommend?", listOf("The MARS agent on each VM", "Microsoft Azure Backup Server on-premises, sending copies to a Recovery Services vault", "Azure Site Recovery", "Azure File Sync"), setOf(1), "Microsoft Azure Backup Server (MABS) runs on-premises and backs up Hyper-V VMs, SQL Server and other workloads with application awareness. It keeps recent copies on local disks for fast restores and sends longer-term copies to Azure.",
                scenario = "Fernbank Council still runs the database for its Android bin-collection app on Hyper-V in the town hall. It needs consistent SQL backups and quick restores without waiting for downloads.",
                whyWrong = mapOf(
                    0 to "MARS backs up files and folders, not whole VMs or SQL databases consistently.",
                    2 to "Site Recovery replicates for disaster recovery. It does not keep a history of backups.",
                    3 to "File Sync syncs file shares, not VMs or databases.",
                ),
            ),
            B.q("sa-m3-33", "sa-backup-dr", "A developer accidentally dropped a whole Azure SQL database yesterday. How do you get it back?", listOf("Restore the deleted database from its automated backups, to a point before it was dropped", "Fail over to a geo-secondary", "Recover it from the Azure activity log", "It cannot be recovered"), setOf(0), "Azure SQL keeps automated backups of a deleted database for its retention period. You can restore it, as it was at the moment of deletion or an earlier point, from the list of deleted databases on the server.",
                scenario = "A cleanup script at Rookwood Games dropped the leaderboard database of its Android game instead of a test copy. Backups use the default seven-day retention, and there is no geo-replica.",
                whyWrong = mapOf(
                    1 to "Failover is for outages. A dropped database is a deliberate change, and here there is no geo-secondary at all.",
                    2 to "The activity log records the deletion but holds no data.",
                    3 to "Deleted databases can be restored within the backup retention period.",
                ),
            ),
            B.q("sa-m3-34", "sa-backup-dr", "VMs in a region with availability zones must recover in another zone of the same region, because data must not leave the region. What do you recommend?", listOf("Azure Site Recovery zone-to-zone disaster recovery", "Cross-region restore from a backup vault", "Azure Site Recovery to the paired region", "Snapshots of the OS disks"), setOf(0), "Site Recovery can replicate VMs from one availability zone to another in the same region, with recovery points and orchestrated failover. The data stays in the region.",
                scenario = "Bergholt Bank must keep data for its Android banking app inside one country, which has a single Azure region with zones. It still needs disaster recovery for its VMs.",
                whyWrong = mapOf(
                    1 to "Cross-region restore copies data to another region, which the rule forbids.",
                    2 to "The paired region is in another country here, so data would leave.",
                    3 to "Snapshots are not orchestrated recovery and stay in the same zone's storage.",
                ),
            ),
            B.q("sa-m3-35", "sa-backup-dr", "Backups must stay recoverable for weeks even if an attacker deletes them, and the protection itself must be impossible to switch off. What do you configure on the vault?", listOf("Enhanced soft delete set to always-on, with a long soft delete period", "Locally redundant storage", "A daily backup report", "A smaller retention period"), setOf(0), "Soft delete keeps deleted backup data for a period, 14 days by default and up to 180 days with enhanced soft delete. Set to always-on, soft delete cannot be turned off, so an attacker cannot remove the safety net.",
                scenario = "Malvern Logistics lost backups in a ransomware attack at a partner company and wants a guarantee for the VMs behind its Android tracking app.",
                whyWrong = mapOf(
                    1 to "Redundancy decides where copies live, not whether a deletion can be undone.",
