            // Infrastructure: compute
            B.q("sa-m3-42", "sa-compute", "When a new order email arrives in a shared mailbox, its attachment must be saved to SharePoint and a row added to a CRM, designed visually by the operations team. What do you recommend?", listOf("Azure Logic Apps with built-in connectors", "A Functions app written in C#", "Azure Batch", "A VM running a scheduled script"), setOf(0), "Logic Apps is a serverless workflow service with hundreds of connectors for services such as Outlook, SharePoint and common CRMs. Workflows are designed in a visual designer, which suits teams that do not write code.",
                scenario = "Cloverleaf Supplies receives orders by email as well as through its Android app. The operations team, who do not code, want to automate the email orders.",
                whyWrong = mapOf(
