            B.q("sa-m3-48", "sa-app-architecture", "Event Grid delivers events to a webhook that is sometimes down for hours. No event may be lost. What do you configure?", listOf("A retry policy, plus a dead-letter destination in Blob Storage for events that cannot be delivered", "A smaller event schema", "A second webhook with the same address", "Nothing: Event Grid stores events forever"), setOf(0), "Event Grid retries delivery with back-off for up to 24 hours by default. With a dead-letter destination, events that still cannot be delivered are written to a storage container instead of being dropped.",
                scenario = "Tealbrook Insurance's claims system receives events for every photo uploaded from its Android app. Its webhook goes down during weekend maintenance and some events vanished.",
